package com.hermesandroid.relay.wake

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.float
import kotlinx.serialization.json.int
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.BeforeClass
import org.junit.Test
import java.io.InputStream

/**
 * Validates the pure-Kotlin [MelSpectrogram] against reference outputs
 * generated by onnxruntime running the real melspectrogram.onnx model
 * (public/mel_test_vectors.json, max onnx-vs-reference diff 1.5e-05).
 */
class MelSpectrogramTest {

    companion object {
        private lateinit var mel: MelSpectrogram
        private lateinit var vectors: JsonArray

        @JvmStatic
        @BeforeClass
        fun load() {
            fun res(name: String): ByteArray =
                (javaClass.classLoader.getResourceAsStream(name)
                    ?: error("missing test resource: $name")).readBytes()
            mel = MelSpectrogram(res("wakeword/mel_weights.bin"))
            vectors = Json.parseToJsonElement(
                res("wakeword/mel_test_vectors.json").inputStream().readBytes().decodeToString()
            ) as JsonArray
        }
    }

    @Test
    fun matchesOnnxReference_allSizes() {
        for (v in vectors) {
            val obj = v as JsonObject
            val n = (obj["n"] as JsonPrimitive).int
            val input = (obj["input"] as JsonArray).map { (it as JsonPrimitive).float }.toFloatArray()
            val expected = (obj["expected_transformed"] as JsonArray)
            assertEquals("input length", n, input.size)

            val frames = (expected as JsonArray).size
            val out = FloatArray(frames * MelSpectrogram.MEL_BINS)
            val gotFrames = mel.transform(input, out)
            assertEquals("frame count for N=$n", frames, gotFrames)

            var maxDiff = 0f
            for (f in 0 until frames) {
                val row = expected[f] as JsonArray
                for (m in 0 until MelSpectrogram.MEL_BINS) {
                    val exp = (row[m] as JsonPrimitive).float
                    val d = Math.abs(exp - out[f * MelSpectrogram.MEL_BINS + m])
                    if (d > maxDiff) maxDiff = d
                }
            }
            assertTrue(
                "N=$n maxDiff=$maxDiff too large (limit 1e-3)",
                maxDiff < 1e-3f
            )
        }
    }

    @Test
    fun rawMode_matchesRawReference() {
        val obj = (vectors[0] as JsonObject)
        val input = (obj["input"] as JsonArray).map { (it as JsonPrimitive).float }.toFloatArray()
        val expected = (obj["expected_raw"] as JsonArray)
        val frames = expected.size
        val out = FloatArray(frames * MelSpectrogram.MEL_BINS)
        mel.transform(input, out, officialTransform = false)
        for (f in 0 until frames) {
            val row = expected[f] as JsonArray
            for (m in 0 until MelSpectrogram.MEL_BINS) {
                val exp = (row[m] as JsonPrimitive).float
                val got = out[f * MelSpectrogram.MEL_BINS + m]
                assertTrue(
                    "raw f=$f m=$m: got=$got expected=$exp",
                    Math.abs(exp - got) < 1e-3f
                )
            }
        }
    }

    @Test
    fun zeroInput_isFinite() {
        val out = FloatArray(8 * MelSpectrogram.MEL_BINS)
        mel.transform(FloatArray(1760), out)
        out.forEach { assertTrue(it.isFinite()) }
        // constant input → constant spectrum floor behavior: all finite,
        // values in a sane range (transformed: ~ -100/10+2 = -8 .. a few dB)
        out.forEach { assertTrue("value $it out of range", it > -50f && it < 50f) }
    }

    @Test(expected = IllegalArgumentException::class)
    fun shortInput_rejected() {
        mel.transform(FloatArray(100), FloatArray(32))
    }

    @Test(expected = IllegalArgumentException::class)
    fun shortOutput_rejected() {
        mel.transform(FloatArray(1760), FloatArray(10))
    }
}
